<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue';
import { HomeFilled, Upload, Document, Operation, DataAnalysis, ChatDotRound, Refresh, Plus, Delete, Edit, Link, ArrowDown, Close, Search, FolderOpened } from '@element-plus/icons-vue';
import LegacyApp from './App.vue';
import catalog from './knowledge-catalog.json';
import DocumentPicker from './DocumentPicker.vue';
import TaskCenter from './TaskCenter.vue';
import ReviewCenter from './ReviewCenter.vue';
import MultimodalSearch from './MultimodalSearch.vue';
import EvidenceCompare from './EvidenceCompare.vue';
import QualityPanel from './QualityPanel.vue';
import { request, streamTurn } from './workbench-api';

const navigation = [
  { id: 'dashboard', name: '总览看板', icon: HomeFilled }, { id: 'upload', name: '上传入库', icon: Upload },
  { id: 'documents', name: '文档管理', icon: Document }, { id: 'chunks', name: 'Chunk 管理', icon: Operation },
  { id: 'retrieval', name: '检索调试', icon: DataAnalysis }, { id: 'agent', name: 'Agent 对话', icon: ChatDotRound },
];
const advanced = [{id:'quality',name:'质量与排错'},{id:'evidence',name:'图文区域对照'},{id:'multimodal',name:'图文联合检索'},{id:'reviews',name:'资料审核'}, {id:'tasks',name:'任务中心'}, {id:'knowledge',name:'知识资产'}, {id:'metadata',name:'元数据'}, {id:'vector',name:'向量索引'}, {id:'graph',name:'知识图谱'}, {id:'ragas',name:'评估中心'}, {id:'api',name:'API 与 SDK'}, {id:'open',name:'项目说明'}];
const readRoute = () => { const key = location.hash.slice(2); return [...navigation, ...advanced].some(p => p.id === key) ? key : 'dashboard'; };
const page = ref(readRoute()), showAdvanced = ref(advanced.some(p => p.id === page.value));
const pageName = computed(() => [...navigation,...advanced].find(p => p.id === page.value)?.name);
const isAdvanced = computed(() => !['tasks','reviews','multimodal','evidence','quality'].includes(page.value)&&advanced.some(p => p.id === page.value));
const useCrossLanguage=ref(true);
const reviewFocus=ref(''),publishedOnly=ref(false),useTableRetrieval=ref(true),useEvidenceRetrieval=ref(true);
const visualFocus=ref(null),evidenceFocus=ref('');
function viewEvidence(doc){evidenceFocus.value=doc.document_id;go('evidence');}
function viewVisual(doc){visualFocus.value={...doc};go('multimodal');}
const taskFocus = ref('');
const online = ref(false), loading = ref(false), error = ref(''), notice = ref(''), busy = ref('');
const connectionError=ref(''),lastSync=ref(null);let reconnectTimer,modeInitialized=false;
const summary = ref(null), documents = ref([]), bases = ref(catalog.map(b=>({...b,document_count:null}))), sessions = ref([]), chunks = ref([]);
const base = ref('automotive'), docFilter = ref(''), search = ref(''), selectedChunkId = ref('');
const sessionPage=ref(1),sessionTotal=ref(0);let sessionListSeq=0;
async function loadSessions(){const seq=++sessionListSeq;try{const h=await request('/sessions?page='+sessionPage.value+'&page_size=30');if(seq!==sessionListSeq)return;sessions.value=h.items;sessionTotal.value=h.total;if(sessionPage.value>Math.max(1,Math.ceil(h.total/30))){sessionPage.value=Math.max(1,Math.ceil(h.total/30));}}catch(e){if(seq===sessionListSeq)error.value='会话列表加载失败：'+e.message;}}
watch(sessionPage,()=>{if(online.value)loadSessions();});
const documentBase=ref(''),documentSearch=ref(''),documentCategory=ref(''),documentPage=ref(0),documentTotal=ref(0),documentLayout=ref('gallery');
const categoryOptions=computed(()=>(summary.value?.categories||[]).filter(c=>!documentBase.value||c.knowledge_base_id===documentBase.value));
watch(documentCategory,()=>{documentPage.value=0;if(online.value)loadDocuments();});
const documentRows=computed(()=>documents.value),visibleDocs=computed(()=>documents.value);
const documentPages=computed(()=>Math.max(1,Math.ceil(documentTotal.value/50)));
const chunkPage=ref(0),chunkTotal=ref(0),selectedRecord=ref(null);
const filteredChunks=computed(()=>chunks.value);
const selectedChunk=computed(()=>selectedChunkId.value?(chunks.value.find(c=>c.chunk_id===selectedChunkId.value)||(selectedRecord.value?.chunk_id===selectedChunkId.value?selectedRecord.value:null)):chunks.value[0]);
let documentSeq=0,chunkSeq=0,searchTimer,chunkTimer;
watch(documentBase,()=>{documentCategory.value='';documentPage.value=0;if(online.value)loadDocuments();});
watch(documentSearch,()=>{documentPage.value=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>online.value&&loadDocuments(),250);});
watch(documentPage,()=>{if(online.value)loadDocuments();});
watch(docFilter,()=>{chunkPage.value=0;if(page.value==='chunks'&&online.value)loadChunks();});
watch(search,()=>{chunkPage.value=0;selectedChunkId.value='';selectedRecord.value=null;clearTimeout(chunkTimer);chunkTimer=setTimeout(()=>page.value==='chunks'&&online.value&&loadChunks(),250);});
watch(chunkPage,()=>{selectedChunkId.value='';selectedRecord.value=null;if(online.value)loadChunks();});
async function loadDocuments(){const seq=++documentSeq;try{const params=new URLSearchParams({page:String(documentPage.value+1),page_size:'50',q:documentSearch.value});if(documentBase.value)params.set('knowledge_base_id',documentBase.value);if(documentCategory.value)params.set('category',documentCategory.value);const result=await request('/documents?'+params);if(seq!==documentSeq)return;documents.value=result.items;documentTotal.value=result.total;if(documentPage.value>=documentPages.value)documentPage.value=documentPages.value-1;}catch(e){if(seq===documentSeq){documents.value=[];documentTotal.value=0;error.value=e.message;}}}
async function loadChunks(){const seq=++chunkSeq;try{const params=new URLSearchParams({page:String(chunkPage.value+1),page_size:'50',q:search.value});if(docFilter.value)params.set('document_id',docFilter.value);const result=await request('/chunks?'+params);let picked=null;if(selectedChunkId.value&&!result.items.some(c=>c.chunk_id===selectedChunkId.value))picked=await request('/chunks/'+encodeURIComponent(selectedChunkId.value));if(seq!==chunkSeq)return;chunks.value=result.items;chunkTotal.value=result.total;selectedRecord.value=picked&&(!docFilter.value||picked.doc_id===docFilter.value)?picked:null;if(selectedChunkId.value&&!selectedRecord.value&&!chunks.value.some(c=>c.chunk_id===selectedChunkId.value))selectedChunkId.value='';if(chunkPage.value>=Math.max(1,Math.ceil(chunkTotal.value/50)))chunkPage.value=Math.max(0,Math.ceil(chunkTotal.value/50)-1);}catch(e){if(seq===chunkSeq){chunks.value=[];chunkTotal.value=0;selectedRecord.value=null;error.value=e.message;}}}
async function loadPage(){if(page.value==='documents')await loadDocuments();if(page.value==='chunks')await loadChunks();}
const selectedFile = ref(null), fileInput = ref(null), parser = ref('auto'), splitter = ref('parent_child');
const textOpen = ref(false), textTitle = ref(''), textBody = ref(''), editOpen = ref(false), editBody = ref('');
const useRerank=ref(true),useCompression=ref(true),useExpansion=ref(false),useImageContext=ref(true);
const query = ref(''), retrieval = ref(null), mode = ref('offline'), topK = ref(5), fusion = ref('rrf'), searchMode = ref('hybrid');
const similarImages=ref(null);
async function findSimilar(doc){similarImages.value=null;await perform('similar',async()=>{similarImages.value=await request(`/documents/${doc.document_id}/similar-images?knowledge_base_id=${doc.knowledge_base_id}&top_k=8`);});}
const currentSession = ref(null), question = ref(''), sending = ref(false), events = ref([]), sources = ref([]), conversation = ref(null);
let refreshSeq = 0, sessionSeq = 0, controller, pendingNotice = '';
let previousFocus;
watch(()=>textOpen.value||editOpen.value,async open=>{if(open){previousFocus=document.activeElement;await nextTick();document.querySelector('.wb-modal input,.wb-modal textarea,.wb-modal select')?.focus();}else previousFocus?.focus();});
function trapDialog(event){if(event.key!=='Tab')return;const nodes=[...event.currentTarget.querySelectorAll('button:not(:disabled),input,textarea,select')];const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
const industryGroups = computed(()=>[{id:'discrete',name:'离散制造'},{id:'process',name:'流程制造'}].map(group=>({...group,items:bases.value.filter(b=>b.primary_industry&&b.industry_group===group.id).map(b=>({...b,children:bases.value.filter(child=>child.parent_id===b.id),total_documents:b.document_count===null?null:b.document_count+bases.value.filter(child=>child.parent_id===b.id).reduce((n,c)=>n+(c.document_count||0),0)}))})));
const supportingBases = computed(()=>bases.value.filter(b=>!b.primary_industry&&!b.parent_id));
const label = id => bases.value.find(b => b.id === id)?.name || id || '—';
const date = value => value ? new Date(value).toLocaleString('zh-CN', { month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false }) : '—';
const score = value => Number.isFinite(value) ? value.toFixed(4) : '—';
const sourcePageUrl=value=>{try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)&&!url.username&&!url.password?url.href:null;}catch{return null;}};
const sourceName = item => item.metadata?.source || documents.value.find(d => d.document_id === (item.doc_id || item.document_id))?.source_name || '来源文档';
const statusLabel = value => ({uploaded:'待解析',indexed:'已入库',processing:'处理中',failed:'失败',completed:'已完成',running:'生成中',cancelled:'已中止',interrupted:'已中断'})[value] || value;
const options = () => ({ runtime_mode: mode.value, retrieval_mode: searchMode.value, fusion_method: fusion.value, top_k: Math.max(30,topK.value), final_top_k:topK.value, query_rewrite:false, query_expansion:useExpansion.value, metadata_router:false, query_transformation:false, parent_recovery:searchMode.value.includes('parent_child'), rerank:useRerank.value, compression:useCompression.value, image_context:useImageContext.value, review_mode:publishedOnly.value?'published_only':'reference',table_retrieval:useTableRetrieval.value,cross_language_query:useCrossLanguage.value,evidence_retrieval:useEvidenceRetrieval.value });
function reviewDoc(doc){reviewFocus.value=doc.document_id;go('reviews');}
function go(id,message='',taskId='') {if(id==='tasks')taskFocus.value=taskId;notice.value=message;pendingNotice=message;location.hash = '#/' + id;}
function routeChanged() { page.value = readRoute(); error.value=''; notice.value=pendingNotice;pendingNotice=''; if(advanced.some(item=>item.id===page.value))showAdvanced.value=true; window.scrollTo(0,0);if(online.value){loadPage();if(page.value==='agent')loadSessions();} }
async function perform(key, action) { if(busy.value)return; busy.value=key; error.value=''; notice.value=''; try { await action(); } catch(e) { error.value=e.message; } finally {busy.value='';} }
async function refresh({quiet=false}={}) {
  if(loading.value)return;
  const seq=++refreshSeq; loading.value=true;
  try {
    const s=await request('/summary');
    if(seq!==refreshSeq)return;
    summary.value=s;bases.value=s.knowledge_bases;online.value=true;connectionError.value='';lastSync.value=new Date();
    sessions.value=s.sessions||[];
    if(!modeInitialized){mode.value=s.status.models.every(m=>m.status==='configured')?'configured':'offline';modeInitialized=true;}
    if(!quiet||page.value==='documents')await loadPage();
    if(page.value==='agent')await loadSessions();
  } catch(e) { if(seq!==refreshSeq)return; online.value=false;connectionError.value=e.message; }
  finally { if(seq===refreshSeq)loading.value=false; }
}
function reconnect(){if(!document.hidden&&!loading.value&&!sending.value)refresh({quiet:online.value});}
function browseBase(id){const parent=bases.value.find(b=>b.id===id);const children=bases.value.filter(b=>b.parent_id===id&&b.document_count>0);const selected=parent?.document_count===0&&children.length===1?children[0].id:id;documentBase.value=selected;base.value=selected;documentSearch.value='';documentPage.value=0;go('documents');}

function viewChunks(doc,message='') {docFilter.value=doc.document_id;search.value='';selectedChunkId.value='';go('chunks',message);}
function debugDoc(doc) {docFilter.value=doc.document_id;base.value=doc.knowledge_base_id||'energy';retrieval.value=null;go('retrieval');}
async function openChunkSource(source) {docFilter.value=source.doc_id;search.value='';chunkPage.value=0;selectedChunkId.value='';selectedRecord.value=null;await nextTick();selectedChunkId.value=source.chunk_id;go('chunks');if(page.value==='chunks')await loadChunks();}
function chooseFile(file) { if(!file)return; if(file.size>64*1024*1024){error.value='文件不能超过 64 MiB';return;} selectedFile.value=file; }
async function upload() { await perform('upload',async()=>{
  if(!selectedFile.value)throw new Error('请先选择文件');
  const data=await request(`/documents/upload?filename=${encodeURIComponent(selectedFile.value.name)}&knowledge_base_id=${base.value}`,{method:'POST',body:selectedFile.value,raw:true});
  if(data.document.status==='indexed'){selectedFile.value=null;if(fileInput.value)fileInput.value.value='';await refresh();viewChunks(data.document,'相同原件已入库，已保留当前编辑内容并复用结果。');return;}
  const task=await request('/tasks',{method:'POST',body:{kind:'process',document_ids:[data.document.document_id],runtime_mode:'offline',process_options:{parser_mode:parser.value,splitter:splitter.value}}});
  await refresh();selectedFile.value=null;if(fileInput.value)fileInput.value.value='';go('tasks','原件已保存，后台解析任务已创建：'+task.task_id,task.task_id);
}); }
async function importText() { await perform('text',async()=>{const result=await request('/documents/text',{method:'POST',body:{title:textTitle.value,content:textBody.value,knowledge_base_id:base.value}});textOpen.value=false;textBody.value='';textTitle.value='';await refresh();viewChunks(result.document);}); }
async function processDoc(doc) {await perform(doc.document_id,async()=>{const task=await request('/tasks',{method:'POST',body:{kind:'process',document_ids:[doc.document_id],runtime_mode:'offline'}});go('tasks','后台解析任务：'+task.task_id,task.task_id);});}
async function rebuild(doc) {await perform(doc.document_id,async()=>{const task=await request('/tasks',{method:'POST',body:{kind:'index',document_ids:[doc.document_id],runtime_mode:mode.value}});go('tasks','后台索引任务：'+task.task_id,task.task_id);});}
async function removeDoc(doc) { if(!confirm(`将“${doc.source_name || doc.title}”移出当前知识库？原件和历史版本保留。`))return;await perform(doc.document_id,async()=>{await request(`/documents/${doc.document_id}`,{method:'DELETE'});docFilter.value='';await refresh();}); }
function openEditor() {editBody.value=selectedChunk.value.content;editOpen.value=true;}
async function changeChunk(change, remove=false) {const chunk=selectedChunk.value;if(!chunk)return;await perform('chunk',async()=>{
  const path=`/chunks/${chunk.chunk_id}`; const revision=chunk.metadata.revision_id;
  await request(remove ? `${path}?expected_revision=${encodeURIComponent(revision)}`:path,{method:remove?'DELETE':'PATCH',body:remove?undefined:{expected_revision:revision,...change}});
  editOpen.value=false;await refresh();notice.value='已保存新版本并同步检索索引。';
});}
async function deleteChunk() {if(confirm('删除当前 Chunk？历史版本仍可追溯。'))await changeChunk({},true);}
async function runRetrieval() {retrieval.value=null;await perform('retrieve',async()=>{retrieval.value=await request('/retrieve',{method:'POST',body:{question:query.value,knowledge_base_id:base.value,document_id:docFilter.value||null,options:options()}});});}
async function openSession(id) {if(sending.value)return;const seq=++sessionSeq;error.value='';try {const result=await request('/sessions/'+id);if(seq!==sessionSeq)return;currentSession.value=result;events.value=result.events||[];sources.value=[...(result.messages.filter(m=>m.role==='assistant').at(-1)?.sources||[])];base.value=result.knowledge_base_id;await scrollChat();}catch(e){if(seq===sessionSeq)error.value=e.message;}}
async function newSession() {if(sending.value)return;await perform('session',async()=>{const result=await request('/sessions',{method:'POST',body:{knowledge_base_id:base.value}});sessionPage.value=1;await refresh();await openSession(result.session_id);});}
async function archiveSession(item) {if(sending.value||!confirm('归档这个会话？记录仍保留在本地。'))return;await perform('archive',async()=>{await request('/sessions/'+item.session_id,{method:'DELETE'});if(currentSession.value?.session_id===item.session_id){currentSession.value=null;events.value=[];sources.value=[];}await refresh();});}
async function scrollChat(){await nextTick();if(conversation.value)conversation.value.scrollTop=conversation.value.scrollHeight;}
async function send() {
  if(sending.value||!question.value.trim())return;
  if(!currentSession.value){await newSession();if(!currentSession.value)return;}
  sending.value=true;error.value='';const session=currentSession.value;const text=question.value;question.value='';events.value=[];sources.value=[];
  session.messages.push({role:'user',content:text,status:'completed',created_at:new Date().toISOString()},{role:'assistant',content:'',status:'running',sources:[]});
  const answer=session.messages.at(-1);controller=new AbortController();await scrollChat();
  try {
    await streamTurn(session.session_id,{question:text,request_id:crypto.randomUUID(),options:options()},controller.signal,event=>{
      if(event.type==='token')answer.content+=event.text;
      else if(event.type==='answer')answer.content=event.text;
      else if(event.type==='sources'){sources.value=event.items;answer.sources=event.items;}
      else {events.value.push(event); if(event.type==='done'){answer.content=event.answer;answer.status='completed';answer.trace_id=event.trace_id;answer.latency_ms=event.latency_ms;sources.value=event.sources;} if(event.type==='error'){answer.status=event.status;error.value=event.message;}}
      scrollChat();
    });
  } catch(e) {answer.status=e.name==='AbortError'?'cancelled':'failed';error.value=e.name==='AbortError'?'已停止接收，后台将记录中断状态。':e.message;}
  finally {sending.value=false;controller=null;await refresh();}
}
const lastDone = computed(()=>[...events.value].reverse().find(e=>e.type==='done'));
const eventText = event => ({session:'会话已加载',tool_start:'检索知识库',tool_end:`检索完成 · ${event.source_count ?? 0} 条来源`,sources:'证据已注入',done:'回答已保存',error:'执行失败',stage:`${({history:'读取历史',prefetch:'预检索',generation:'生成回答'})[event.stage]||event.stage} · ${event.status}`})[event.type] || event.type;
onMounted(async()=>{window.addEventListener('hashchange',routeChanged);window.addEventListener('online',reconnect);document.addEventListener('visibilitychange',reconnect);reconnectTimer=setInterval(reconnect,10000);await refresh();window.scrollTo(0,0);});
onUnmounted(()=>{clearInterval(reconnectTimer);window.removeEventListener('online',reconnect);document.removeEventListener('visibilitychange',reconnect);window.removeEventListener('hashchange',routeChanged);controller?.abort();refreshSeq++;sessionSeq++;documentSeq++;chunkSeq++;clearTimeout(searchTimer);clearTimeout(chunkTimer);});
</script>

<template>
  <div class="wb-shell">
    <aside class="wb-sidebar">
      <a class="wb-brand wb-card" href="#/dashboard"><span class="wb-logo">MI</span><span><strong>制造能源工业</strong><span>知识库系统<br>知识检索与 Agent 控台</span></span></a>
      <nav class="wb-nav" aria-label="主导航"><a v-for="item in navigation" :key="item.id" :href="'#/'+item.id" :class="{active:page===item.id}" :aria-current="page===item.id?'page':undefined"><component :is="item.icon"/><span>{{ item.name }}</span></a></nav>
      <section class="wb-card wb-health"><div class="wb-between"><div><small>链路状态</small><strong>{{ online?'后端已连接':'后端未连接' }}</strong></div><span class="wb-badge" :class="online?'green':'gray'">{{online?'READY':'OFFLINE'}}</span></div><div class="wb-chips"><span><Link/> SQLite <i :class="{on:online}"/></span><span title="本地向量索引"><Link/> index <i :class="{on:online}"/></span><span :title="summary?.status?.agent_runtime==='langgraph'?'LangGraph 工作流':'Agent 待配置'"><Link/> agent <i :class="{on:online&&summary?.status?.agent_runtime==='langgraph'}"/></span></div></section>
      <details class="wb-advanced" :open="showAdvanced"><summary @click.prevent="showAdvanced=!showAdvanced">高级工具 <ArrowDown/></summary><a v-for="item in advanced" :key="item.id" :href="'#/'+item.id" :class="{active:page===item.id}">{{item.name}}</a></details>
    </aside>
    <main class="wb-main">
      <header class="wb-card wb-header"><div><small>WORKSPACE</small><h1>{{ pageName }}</h1></div><div class="wb-actions"><button class="wb-button" @click="go('quality')">质量与排错</button><button class="wb-button" :disabled="loading" @click="refresh"><Refresh :class="{spinning:loading}"/>{{loading?'正在刷新':'刷新数据'}}</button></div></header>
      <div v-if="error" class="wb-alert error" role="alert">{{error}}<button aria-label="关闭错误" @click="error=''"><Close/></button></div>
      <div v-if="notice" class="wb-alert" role="status">{{notice}}</div>
      <div v-if="connectionError" class="wb-alert error" role="status">{{connectionError}}。每 10 秒自动重连。<span v-if="lastSync"> 当前展示 {{date(lastSync)}} 的最近成功记录，数量可能已变化。</span><span v-else> 行业分类已显示，资料数量等待连接后加载。</span><button class="wb-button" :disabled="loading" @click="refresh">立即重试</button></div>

      <template v-if="page==='dashboard'">
        <section class="wb-card wb-hero"><div class="wb-hero-copy"><small>RAG PRODUCT SURFACE</small><h2>从文档入库 / OCR 图片表格识别、Chunk 观测到 Agent 溯源对话，构建制造能源工业知识工作台</h2><p>这里汇聚文档、检索、Agent 会话和系统依赖的核心状态。你可以从总览跳入任意模块，直接进行上传、切分检查、检索调试和会话回放。</p></div><div class="wb-actions"><button class="wb-button primary" @click="go('upload')">开始导入文档</button><button class="wb-button" @click="go('agent')">打开 Agent 对话</button></div></section>
        <div v-if="summary?.image_count" class="wb-alert" role="status">图文资料 {{summary.image_count}} 张 · 已完成 OCR 与视觉索引 {{summary.analyzed_image_count}} 张 · 识别出文字 {{summary.ocr_with_text}} 张<button class="wb-button tiny" @click="go('tasks')">查看处理任务</button></div><section class="wb-kpis"><article class="wb-card" v-for="item in [{name:'知识文档',value:summary?.document_count,detail:'已保存文档总数'},{name:'切分 Chunk',value:summary?.chunk_count,detail:'当前文档切分总量'},{name:'最近会话',value:summary?.session_count,detail:'已记录的 Agent 会话'},{name:'后端状态',value:online?'在线':'离线',detail:'SQLite / 本地向量索引 / Agent'}]" :key="item.name"><p>{{item.name}}</p><strong>{{item.value ?? '—'}}</strong><p>{{item.detail}}</p></article></section>
        <div class="wb-two"><section class="wb-card"><div class="wb-between"><div><small>DOCUMENTS</small><h3>最近文档</h3></div><button class="wb-link" @click="go('documents')">查看全部</button></div><div v-if="!summary?.document_count" class="wb-empty">{{summary?'还没有文档，上传资料即可开始。':'资料记录正在连接，尚未取得数量。'}}</div><div v-for="doc in (summary?.documents||[]).slice(0,4)" :key="doc.document_id" class="wb-recent"><div><strong>{{doc.source_name||doc.title}} <span v-if="doc.data_source==='demo'" class="wb-demo">演示</span></strong><p>{{doc.file_type}} · {{doc.chunk_count}} chunks · {{date(doc.updated_at)}}</p></div><button class="wb-button tiny" @click="viewChunks(doc)">查看切分</button></div></section><section class="wb-card"><div class="wb-between"><div><small>SESSIONS</small><h3>最近会话</h3></div><button class="wb-link" @click="go('agent')">进入对话</button></div><div v-if="!sessions.length" class="wb-empty">{{summary?'还没有会话。选择知识库，开始第一次提问。':'会话记录等待连接后加载。'}}</div><button v-for="item in sessions.slice(0,3)" :key="item.session_id" class="wb-session-preview" @click="go('agent');openSession(item.session_id)"><strong>{{item.title}}</strong><p>{{item.message_count}} 条消息 · {{date(item.updated_at)}}</p><p class="wb-clamp">{{item.preview}}</p></button></section></div>
        <section class="wb-card wb-industry-spaces"><div class="wb-between"><div><small>INDUSTRIAL KNOWLEDGE</small><h3>行业知识空间</h3></div><span class="wb-muted">围绕研发与生产，按行业组织资料</span></div><div v-for="group in industryGroups" :key="group.id" class="wb-industry-group"><h4>{{group.name}}</h4><div class="wb-domains"><article v-for="item in group.items" :key="item.id" :data-industry-id="item.id" class="wb-domain-family"><button class="wb-domain-entry" @click="browseBase(item.id)"><strong>{{item.name}}</strong><p>{{item.description}}</p><span>{{item.modules.join(' / ')}}</span><em>{{item.total_documents??'—'}} 篇文档 <span v-if="item.children.length">· 含专属子库</span><span v-else-if="item.total_documents===0">· 待填充</span></em></button><div v-if="item.children.length" class="wb-domain-children"><button v-for="child in item.children" :key="child.id" @click="browseBase(child.id)"><small>专属子库</small><strong>{{child.name}}</strong><p>{{child.document_count??'—'}} 篇文档 · 单独选择使用</p></button></div></article></div></div><details class="wb-supporting-spaces"><summary>通用、专属与历史知识空间</summary><div class="wb-domains"><button v-for="item in supportingBases" :key="item.id" @click="browseBase(item.id)"><strong>{{item.name}}</strong><p>{{item.description}}</p><span>{{item.modules.join(' / ')}}</span><em>{{item.document_count??'—'}} 篇文档</em></button></div></details></section>
      </template>

      <template v-else-if="page==='upload'">
        <section class="wb-card wb-intro"><div><small>DEDICATED INGESTION</small><h2>上传文档并解析入向量数据库</h2><p>上传 → 解析 → 切分 → 写入索引，完成后直接进入 Chunk 管理查看切分和溯源结果。</p></div><div class="wb-actions"><button class="wb-button" @click="refresh"><Refresh/>刷新数据</button><button class="wb-button" @click="go('documents')"><FolderOpened/>查看文档列表</button></div></section>
        <div class="wb-two wb-upload-grid"><section class="wb-card"><div class="wb-between"><div><small>UPLOAD FILE</small><h3>文件上传入库</h3></div><span class="wb-badge">推荐主流程</span></div><form @submit.prevent="upload"><label class="wb-field">知识库名称<select v-model="base"><option v-for="b in bases" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label class="wb-field">切分策略<select v-model="splitter"><option value="parent_child">自动判断 / 结构保护与父子切分</option><option value="markdown_header">按章节标题</option><option value="recursive">递归切分</option><option value="business_object">业务对象切分</option></select></label><label class="wb-field">文件选择</label><button type="button" class="wb-dropzone" @dragover.prevent @drop.prevent="chooseFile($event.dataTransfer.files[0])" @click="fileInput.click()"><Upload/><span v-if="selectedFile">{{selectedFile.name}}</span><span v-else>拖拽文件到这里，或 <em>点击选择文件</em></span><small>PDF / DOCX / Markdown / TXT / 图片 / 表格 · 最大 64 MiB</small></button><input ref="fileInput" class="wb-file-input" type="file" accept=".pdf,.docx,.md,.txt,.html,.csv,.xlsx,.jsonl,.png,.jpg,.jpeg,.webp,.tif,.tiff,.bmp" @change="chooseFile($event.target.files[0])"/><label class="wb-field">解析路径<select v-model="parser"><option value="auto">原生优先，低文本页面自动 OCR</option><option value="native">仅原生解析</option><option value="ocr">强制 OCR（PDF / 图片）</option></select></label><button class="wb-button primary" :disabled="!!busy||!selectedFile||!online"><Upload/>{{busy==='upload'?'正在入库…':'开始上传入库'}}</button></form></section><section class="wb-card"><small>PIPELINE</small><h3>执行说明</h3><ol class="wb-pipeline"><li><strong>上传源文件</strong><p>选择文档后保存原始文件，并记录文件指纹、所属知识库和版本。</p></li><li><strong>解析与 OCR</strong><p>优先提取原生文本，按页面文本密度选择 OCR。识别结果保留页码与解析路径。</p></li><li><strong>自动切分</strong><p>依次组织 Document、Section、Chunk，保护表格与图片块，保留来源元数据。</p></li><li><strong>写入索引</strong><p>建立向量副本和关键词索引，可独立重建，不覆盖人工编辑的 Chunk。</p></li><li><strong>跳转验证</strong><p>进入 Chunk 管理检查解析结果，再通过检索调试和 Agent 对话验证来源。</p></li></ol><div class="wb-note">图片 OCR、模型可见内容描述和来源核对分别保存，可在资料画廊查看。未由来源确认的工况、数值和缺陷根因保持未知。</div></section></div>
      </template>

      <template v-else-if="page==='documents'">
        <section class="wb-card wb-intro"><div><small>INGESTION PIPELINE</small><h2>文档入库与索引重建</h2><button class="wb-link" @click="go('tasks')">查看后台任务与批量索引</button><p>支持文件上传、纯文本导入、切分策略选择与索引重建，结果同步到文档列表和 Chunk 管理页。</p></div><div class="wb-actions"><button class="wb-button" @click="refresh"><Refresh/>刷新列表</button><button class="wb-button" @click="textOpen=true"><Plus/>纯文本入库</button><button class="wb-button primary" @click="go('upload')"><Upload/>上传文件</button></div></section>
        <section class="wb-card"><div class="wb-between"><div><small>DOCUMENTS</small><h3>知识文档列表</h3></div><span class="wb-badge">{{summary?.document_count||0}} 份文档</span></div><div class="wb-document-filters"><select v-model="documentBase" aria-label="文档知识库"><option value="">全部知识库</option><option v-for="b in bases" :key="b.id" :value="b.id">{{b.name}}</option></select><select v-model="documentCategory" aria-label="资料分类"><option value="">全部分类</option><option v-for="c in categoryOptions" :key="c.knowledge_base_id+c.name" :value="c.name">{{c.name}}（{{c.count}}）</option></select><label class="wb-search"><Search/><input v-model="documentSearch" aria-label="搜索文档" placeholder="搜索图片介绍、分类或文件名"/></label><span class="wb-muted">{{documentTotal}} 份 · 每页 50 份</span></div><div class="wb-actions"><button class="wb-button" @click="documentLayout='gallery'" :aria-pressed="documentLayout==='gallery'">图文浏览</button><button class="wb-button" @click="documentLayout='table'" :aria-pressed="documentLayout==='table'">表格管理</button></div>
          <div v-if="documentLayout==='gallery'" class="wb-image-gallery"><article v-for="doc in visibleDocs" :key="doc.document_id" class="wb-image-card"><button class="wb-image-open" @click="viewChunks(doc)"><img v-if="doc.image_sha256" :src="`/api/v2/workbench/documents/${doc.document_id}/preview?revision_id=${doc.revision_id}`" :alt="doc.source_caption||doc.source_name" loading="lazy"/><span v-else class="wb-file-placeholder">{{doc.file_type}}</span><strong>{{doc.source_caption||doc.source_name||doc.title}}</strong></button><p>{{label(doc.knowledge_base_id)}} · {{doc.assigned_category||'文本资料'}}</p><p v-if="doc.image_sha256">{{doc.ocr_status==='completed'?'OCR 已识别文字':doc.ocr_status==='no_text'?'OCR 未检测到文字':'OCR 待处理'}} · {{doc.visual_embedding_dimension?doc.visual_embedding_dimension+'d 视觉索引':'视觉索引待处理'}}</p><p v-if="doc.frame_count>1">动图帧 {{doc.frames_processed}} / {{doc.frame_count}}</p><p>来源待核验<span v-if="doc.saved_kind==='google_preview'"> · 搜索预览图</span></p><p>文本向量 {{doc.text_embedding_count??'—'}} / {{doc.active_chunk_count??doc.chunk_count}} · {{doc.chunk_count}} chunks</p><div class="wb-actions"><button class="wb-button tiny" @click="reviewDoc(doc)">审核资料</button><button class="wb-button tiny" @click="viewChunks(doc)">原图与证据</button><button v-if="doc.image_sha256" class="wb-button tiny" @click="viewVisual(doc)">视觉观察</button><button v-if="doc.image_sha256" class="wb-button tiny" @click="viewEvidence(doc)">区域对照</button><button class="wb-button tiny" @click="debugDoc(doc)">检索</button><a v-if="sourcePageUrl(doc.source_page)" class="wb-button tiny" :href="sourcePageUrl(doc.source_page)" target="_blank" rel="noopener noreferrer">来源网页</a><button v-if="doc.image_analysis_key" class="wb-button tiny" :disabled="!!busy" @click="findSimilar(doc)">找相似图</button></div></article></div>
          <p v-if="documentLayout==='gallery'&&!visibleDocs.length" class="wb-empty">{{online?'没有符合筛选条件的资料。':'等待连接后加载资料。'}}</p><section v-if="similarImages" class="wb-similar"><div class="wb-between"><h3>相似图片 · 同知识空间</h3><button class="wb-button tiny" @click="similarImages=null">关闭</button></div><p class="wb-muted">{{similarImages.interpretation}}</p><div class="wb-image-gallery"><button v-for="item in similarImages.items" :key="item.document_id" class="wb-image-card" @click="viewChunks(item)"><img :src="`/api/v2/workbench/documents/${item.document_id}/preview?revision_id=${item.revision_id}`" :alt="item.title" loading="lazy"/><strong>{{item.title}}</strong><p>相似度 {{score(item.score)}}</p></button></div><p v-if="!similarImages.items.length">此知识空间暂无其他已处理图片。</p></section>
          <div v-show="documentLayout==='table'" class="wb-table-scroll"><table class="wb-table"><thead><tr><th>文件名</th><th>知识库</th><th>类型</th><th>Chunks</th><th>大小</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="doc in visibleDocs" :key="doc.document_id"><td><strong>{{doc.source_name||doc.title}}</strong><span v-if="doc.data_source==='demo'" class="wb-demo">演示</span><small v-if="doc.status!=='indexed'">{{statusLabel(doc.status)}}</small></td><td>{{label(doc.knowledge_base_id||'energy')}}</td><td>{{doc.file_type}}</td><td>{{doc.chunk_count}}</td><td>{{doc.size_bytes ? (doc.size_bytes/1024).toFixed(1)+' KB':'—'}}</td><td>{{date(doc.updated_at)}}</td><td><div class="wb-actions compact"><button class="wb-button tiny" @click="viewChunks(doc)">查看切分</button><button class="wb-button tiny" @click="debugDoc(doc)">检索调试</button><button v-if="doc.status==='indexed'" class="wb-button tiny" :disabled="!!busy" @click="rebuild(doc)">重建索引</button><button v-else class="wb-button tiny" :disabled="!!busy" @click="processDoc(doc)">解析入库</button><button class="wb-button tiny danger" :disabled="!!busy" @click="removeDoc(doc)">删除</button></div></td></tr></tbody></table><div v-if="!summary?.document_count" class="wb-empty">知识库暂无文档，点击“上传文件”或“纯文本入库”开始。</div><div v-else-if="!documentTotal" class="wb-empty">没有符合当前知识库和文件名筛选条件的文档。</div></div><div v-if="documentPages>1" class="wb-between wb-pagination"><button class="wb-button" :disabled="documentPage===0" @click="documentPage--">上一页</button><span>{{documentPage+1}} / {{documentPages}}</span><button class="wb-button" :disabled="documentPage+1>=documentPages" @click="documentPage++">下一页</button></div><p class="wb-footnote">删除会移出当前检索范围，原件与历史版本仍保留。重建索引使用当前 Chunk 内容。</p></section>
      </template>

      <template v-else-if="page==='chunks'">
        <section class="wb-card wb-intro"><div><small>CHUNK EXPLORER</small><h2>切分结果观测与编辑</h2><p>支持按文档过滤、全文搜索、查看元数据、启停检索并直接编辑 Chunk 内容，便于验证切分质量和溯源字段。</p></div><div class="wb-filter-stack"><DocumentPicker v-model="docFilter" label="筛选文档" @update:modelValue="selectedChunkId='';selectedRecord=null"/><div class="wb-actions"><label class="wb-search"><Search/><input v-model="search" aria-label="搜索 Chunk 内容" placeholder="搜索 chunk 内容"/></label><button class="wb-button" @click="refresh"><Refresh/>刷新</button></div></div></section>
        <div class="wb-chunk-grid"><section class="wb-card"><div class="wb-between"><div><small>LIST</small><h3>Chunk 列表</h3></div><span class="wb-badge">{{chunkTotal}}</span></div><div class="wb-chunk-list"><button v-for="(chunk,i) in filteredChunks" :key="chunk.chunk_id" :class="{active:chunk.chunk_id===selectedChunk?.chunk_id}" @click="selectedChunkId=chunk.chunk_id"><div class="wb-between"><strong>#{{chunkPage*50+i+1}}</strong><span class="wb-state" :class="chunk.enabled?'enabled':'disabled'">{{chunk.enabled?'启用':'停用'}}</span></div><p>{{chunk.content.slice(0,200)}}{{chunk.content.length>200?'…':''}}</p></button><div v-if="!filteredChunks.length" class="wb-empty">没有符合筛选条件的 Chunk。</div></div><div v-if="chunkTotal>50" class="wb-between wb-pagination"><button class="wb-button tiny" :disabled="chunkPage===0" @click="chunkPage--">Chunk 上一页</button><span>{{chunkPage+1}} / {{Math.ceil(chunkTotal/50)}}</span><button class="wb-button tiny" :disabled="(chunkPage+1)*50>=chunkTotal" @click="chunkPage++">Chunk 下一页</button></div></section><section class="wb-card wb-chunk-detail"><div class="wb-between"><div><small>DETAIL</small><h3>Chunk 详情</h3></div><div v-if="selectedChunk" class="wb-actions"><button class="wb-button danger" :disabled="!!busy" @click="deleteChunk"><Delete/>删除</button><button class="wb-button primary" @click="openEditor"><Edit/>编辑</button></div></div><template v-if="selectedChunk"><dl class="wb-meta"><div><dt>ID</dt><dd :title="selectedChunk.chunk_id">{{selectedChunk.chunk_id}}</dd></div><div><dt>Document ID</dt><dd>{{selectedChunk.doc_id}}</dd></div><div><dt>Section</dt><dd>{{selectedChunk.metadata.section||'正文'}}</dd></div><div><dt>Page</dt><dd>{{selectedChunk.metadata.page??'—'}}</dd></div><div><dt>Tokens（估算）</dt><dd>{{selectedChunk.token_count}}</dd></div><div><dt>Start / End Offset</dt><dd>{{selectedChunk.metadata.start_offset??'—'}} / {{selectedChunk.metadata.end_offset??'—'}}</dd></div><div><dt>解析路径</dt><dd>{{selectedChunk.metadata.parse_route||selectedChunk.metadata.parser||'原生文本'}}</dd></div><div><dt>Vector 副本</dt><dd>{{selectedChunk.vector_records.length}} <span v-for="v in selectedChunk.vector_records" :key="v.vector_id" class="wb-vector-label">{{v.model}} / {{v.dimension}}d</span></dd></div></dl><div class="wb-actions wb-detail-actions"><button class="wb-button" :disabled="!!busy" @click="changeChunk({enabled:!selectedChunk.enabled})">{{selectedChunk.enabled?'停用检索':'启用检索'}}</button><a v-if="!selectedChunk.metadata.data_source||selectedChunk.metadata.data_source!=='demo'" class="wb-button" :href="`/api/v2/workbench/documents/${selectedChunk.doc_id}/source?revision_id=${selectedChunk.metadata.revision_id||''}`">下载来源原件</a></div><figure v-if="selectedChunk.metadata.image_sha256" class="wb-original-image"><img :src="`/api/v2/workbench/documents/${selectedChunk.doc_id}/preview?revision_id=${selectedChunk.metadata.revision_id||''}`" :alt="sourceName(selectedChunk)" loading="lazy"/><figcaption>图片原件 · {{selectedChunk.metadata.ocr_status==='completed'?'已完成 OCR 文字识别；原图与来源介绍均保留，内容未人工核验':selectedChunk.metadata.ocr_status==='no_text'?'未检测到文字；可通过来源介绍和相似图片检索':'来源介绍未核验，图片处理状态见元数据'}}</figcaption></figure><div v-if="selectedChunk.metadata.source_system" class="wb-note">{{selectedChunk.metadata.source_system}}专属 · {{selectedChunk.metadata.evidence_kind==='training_reference'?'文本训练参考，尚未独立核验为工艺事实':selectedChunk.metadata.evidence_kind==='source_caption'?'来源图文参考':'用户上传资料，审核状态见元数据'}}</div><article class="wb-content-box"><h4>内容正文</h4><p>{{selectedChunk.content}}</p></article><details class="wb-raw"><summary>完整元数据与向量记录</summary><pre>{{JSON.stringify({metadata:selectedChunk.metadata,vectors:selectedChunk.vector_records},null,2)}}</pre></details></template><div v-else class="wb-empty">选择左侧 Chunk，查看正文与来源。旧版或已删除 Chunk 的内容请在对话来源中查看。</div></section></div>
      </template>

      <template v-else-if="page==='retrieval'">
        <section class="wb-card wb-intro"><div><small>RETRIEVAL DEBUGGER</small><h2>混合检索与来源观测</h2><p>对比向量召回、关键词匹配与融合排序，检查文件名、页码和命中证据。</p></div></section><section class="wb-card"><form @submit.prevent="runRetrieval"><div class="wb-search-options"><label class="wb-field">知识库<select v-model="base" @change="docFilter=''" ><option v-for="b in bases" :key="b.id" :value="b.id">{{b.name}}</option></select></label><div class="wb-field">文档<DocumentPicker v-model="docFilter" :knowledge-base-id="base" label="检索文档"/></div><label class="wb-field">运行模式<select v-model="mode"><option value="offline">离线验证</option><option value="configured">真实模型</option></select></label><label class="wb-field">召回策略<select v-model="searchMode"><option value="hybrid">混合检索</option><option value="vector">向量检索</option><option value="bm25">BM25</option><option value="parent_child">父子上下文</option><option value="parent_child_hybrid">父子混合检索</option><option value="summary">摘要检索</option><option value="rag_fusion">多查询 RAG-Fusion</option></select></label><label class="wb-field">融合<select v-model="fusion"><option value="rrf">RRF</option><option value="weighted">加权</option></select></label><label class="wb-field">Top K<input v-model.number="topK" type="number" min="1" max="30"/></label></div><div class="wb-actions wb-retrieval-toggles"><label><input v-model="useRerank" type="checkbox"/> 重排序</label><label><input v-model="useCompression" type="checkbox"/> 上下文压缩</label><label><input v-model="useExpansion" type="checkbox"/> 查询扩展</label><label><input v-model="useImageContext" type="checkbox"/> 关联图片 OCR</label><label><input v-model="useTableRetrieval" type="checkbox"/> 表格与中英术语增强</label><label><input v-model="useEvidenceRetrieval" type="checkbox"/> 正文条件与图片标题匹配</label><label><input v-model="useCrossLanguage" type="checkbox"/> 中文问题检索英文原文（本机翻译）</label><label><input v-model="publishedOnly" type="checkbox"/> 只检索已审核发布资料</label></div><div class="wb-query-row"><input v-model="query" aria-label="检索问题" placeholder="输入术语、字段名、工艺步骤或设备故障…" required/><button class="wb-button primary" :disabled="!!busy||!online"><Search/>{{busy==='retrieve'?'检索中…':'开始检索'}}</button></div></form></section><section class="wb-card"><div class="wb-between"><div><small>SEARCH RESULTS</small><h3>检索结果</h3></div><span class="wb-badge">{{retrieval?.reranked_docs?.length??0}} 条命中</span></div><div v-if="!retrieval" class="wb-empty">输入问题后，查看每个 Chunk 的召回来源和评分。</div><template v-else><p v-for="warning in retrieval.warnings" :key="warning" class="wb-note">{{warning}}</p><p class="wb-muted">Trace {{retrieval.trace_id}} · {{retrieval.latency_ms.total??'—'}} ms · {{mode==='offline'?'离线评分':'真实模型'}}</p><div v-if="!retrieval.reranked_docs.length" class="wb-empty">当前知识库和过滤条件下没有可用证据。</div><article v-for="(hit,i) in retrieval.reranked_docs" :key="hit.chunk_id" class="wb-hit"><div class="wb-between"><strong>#{{i+1}} {{sourceName(hit)}}</strong><span>Page {{hit.metadata.page??'—'}}</span></div><div class="wb-score-row"><span v-for="s in hit.retrieval_sources" :key="s">{{s}}</span><span>Vector {{score(hit.vector_score)}}</span><span>BM25 {{score(hit.bm25_score)}}</span><span>融合 {{score(hit.metadata?.table_fusion_score??hit.metadata?.evidence_fusion_score??hit.fusion_score)}}</span><span>Rerank {{score(hit.rerank_score)}}</span></div><img v-if="hit.metadata.image_sha256" class="wb-hit-image" :src="`/api/v2/workbench/documents/${hit.doc_id}/preview?revision_id=${hit.metadata.revision_id}`" :alt="hit.metadata.source_caption||sourceName(hit)" loading="lazy"/><p class="wb-muted">{{hit.metadata.evidence_kind==='image_text_context'?'图片介绍 + OCR 上下文 · 自动识别未审核':hit.metadata.evidence_kind==='ocr_text'?'图片 OCR 证据 · 自动识别未审核':hit.metadata.evidence_kind==='source_caption'?'来源介绍 · 未核验':'文档证据'}} · {{hit.metadata.assigned_category||hit.metadata.section}}</p><p v-if="hit.metadata.selection_reason" class="wb-note">{{hit.metadata.selection_reason==='exact_source_caption_requested'?'精确匹配所查图片的来源标题':hit.metadata.selection_reason==='multiple_explicit_source_headers'?'匹配明确表头：'+hit.metadata.matched_source_headers.join('、'):hit.metadata.selection_reason==='exact_table_header_row_key'?'精确匹配表头与行键：'+hit.metadata.matched_table_row_key:hit.metadata.selection_reason==='exact_table_cell_name'?'精确匹配来源单元格：'+hit.metadata.matched_table_cells.join('、'):hit.metadata.selection_reason==='table_scope_note_with_matching_title'?'匹配表格标题及适用范围说明':hit.metadata.selection_reason==='source_cell_checked_table_supersedes_same_figure_machine_ocr'?'采用同图已逐格核对的表格，替代机器 OCR':'来源选择依据：'+hit.metadata.selection_reason}}</p><p>{{hit.content}}</p><button class="wb-link" @click="openChunkSource(hit)">{{hit.chunk_id}} · 查看 Chunk</button></article><details class="wb-raw"><summary>完整检索 Trace</summary><pre>{{JSON.stringify(retrieval,null,2)}}</pre></details></template></section>
      </template>

      <template v-else-if="page==='agent'">
        <section class="wb-card wb-intro"><div><small>AGENT CONSOLE</small><h2>多轮对话、工具调用与溯源结果全链路观测</h2><p>查看会话历史、实时生成内容、工具调用过程，以及最终命中的来源 Chunk。</p></div><div class="wb-actions"><span class="wb-badge" :class="online?'green':'gray'">{{online?'后端可用':'未连接'}}</span><button class="wb-button" @click="refresh"><Refresh/>刷新会话</button><button class="wb-button" :disabled="sending||!!busy" @click="newSession"><Plus/>新建会话</button></div></section>
        <div class="wb-agent-grid"><section class="wb-card wb-session-card"><div class="wb-between"><div><small>SESSIONS</small><h3>会话列表</h3></div><span class="wb-badge">{{sessions.length}}</span></div><label class="wb-field compact">新会话知识库<select v-model="base" :disabled="sending"><option v-for="b in bases" :key="b.id" :value="b.id">{{b.name}}</option></select></label><div class="wb-actions"><button class="wb-link" :disabled="sessionPage===1" @click="sessionPage--">上一页会话</button><span>{{sessionPage}} / {{Math.max(1,Math.ceil(sessionTotal/30))}} · {{sessionTotal}} 条</span><button class="wb-link" :disabled="sessionPage*30>=sessionTotal" @click="sessionPage++">下一页会话</button></div><div class="wb-session-list"><div v-for="item in sessions" :key="item.session_id" class="wb-session-row" :class="{active:currentSession?.session_id===item.session_id}"><button :disabled="sending" @click="openSession(item.session_id)"><strong>{{item.title}}</strong><p>{{item.message_count}} 条 · {{date(item.updated_at)}}</p><p class="wb-clamp">{{item.preview||label(item.knowledge_base_id)}}</p></button><button class="wb-icon-button danger" aria-label="归档会话" :disabled="sending" @click="archiveSession(item)"><Delete/></button></div><div v-if="!sessions.length" class="wb-empty">暂无会话</div></div></section>
          <section class="wb-card wb-conversation-card"><div class="wb-between"><div><small>CONVERSATION</small><h3>对话窗口</h3></div><span class="wb-badge">{{currentSession?.messages?.length||0}} 条记录</span></div><div ref="conversation" class="wb-conversation"><div v-if="!currentSession?.messages?.length" class="wb-empty"><ChatDotRound/><h3>让每个回答都有据可查</h3><p>选择知识库并提问，系统先检索证据，再生成回答。</p></div><article v-for="(message,i) in currentSession?.messages||[]" :key="message.message_id||i" class="wb-message" :class="message.role"><div class="wb-message-meta">{{message.role==='user'?'我':'Agent'}} <span>{{date(message.created_at)}}</span></div><p>{{message.content||'正在检索与生成…'}}</p><template v-if="message.role==='assistant'"><div class="wb-message-tags"><span>{{statusLabel(message.status)}}</span><span>sources: {{message.sources?.length||0}}</span></div><div v-if="message.sources?.length" class="wb-message-files">检索命中文档：{{[...new Set(message.sources.map(sourceName))].join(' / ')}}</div><p v-if="message.error" class="wb-error-text">{{message.error}}</p></template></article></div><form class="wb-composer" @submit.prevent="send"><textarea v-model="question" aria-label="对话问题" :disabled="sending" placeholder="输入问题，例如：总结这份工艺资料，并给出来源 Chunk" @keydown.ctrl.enter.prevent="send" @keydown.meta.enter.prevent="send"/><div class="wb-between"><label><input v-model="publishedOnly" type="checkbox" :disabled="sending"/> 只使用已审核发布资料</label><select v-model="mode" aria-label="问答运行模式" :disabled="sending"><option value="offline">离线验证</option><option value="configured">真实模型 · 已配置服务</option></select><button v-if="sending" type="button" class="wb-button" @click="controller?.abort()">停止生成</button><button v-else class="wb-button primary" :disabled="!question.trim()||!online">发送</button></div><small>下一轮 · {{currentSession?label(currentSession.knowledge_base_id):label(base)}} · {{mode==='configured'?'使用已配置的模型服务':'离线证据摘录，不调用大模型'}}</small></form></section>
          <section class="wb-card wb-trace-card"><div class="wb-between"><div><small>TRACE</small><h3>执行轨迹与来源</h3></div><span class="wb-badge">{{events.length}} 个事件</span></div><dl class="wb-meta"><div><dt>Session</dt><dd>{{currentSession?.session_id||'—'}}</dd></div><div><dt>Route</dt><dd>{{lastDone?.route||'—'}}</dd></div><div><dt>Latency</dt><dd>{{lastDone?.latency_ms?Math.round(lastDone.latency_ms)+' ms':'—'}}</dd></div><div><dt>Source Chunks</dt><dd>{{sources.length}}</dd></div></dl><h4>工具事件</h4><ol class="wb-events"><li v-for="(event,i) in events" :key="event.event_id||i">{{eventText(event)}}</li></ol><p v-if="!events.length" class="wb-muted">暂无执行事件</p><h4>来源 Chunk</h4><article v-for="(source,i) in sources" :key="source.chunk_id" class="wb-source"><strong>{{sourceName(source)}}</strong><p>ref #{{i+1}} · page {{source.metadata?.page??'—'}}</p><button class="wb-link" @click="openChunkSource(source)">{{source.chunk_id}} · 当前 Chunk</button><p>{{source.content}}</p><a v-if="source.source_url&&source.metadata?.data_source!=='demo'" :href="source.source_url">下载来源原件</a><div class="wb-source-scores">Vector {{score(source.vector_score)}}<br>BM25 {{score(source.bm25_score)}} · RRF {{score(source.fusion_score)}}</div></article><p v-if="!sources.length" class="wb-muted">当前回答没有知识库来源。</p></section></div>
      </template>
      <MultimodalSearch v-if="page==='multimodal'" :bases="bases" :initial-document="visualFocus" @task="id=>go('tasks','',id)" @document="viewChunks" @compare="viewEvidence"/>
      <TaskCenter v-else-if="page==='tasks'" :bases="bases" :initial-task-id="taskFocus"/>
      <ReviewCenter v-else-if="page==='reviews'" :bases="bases" :initial-document-id="reviewFocus" @view-chunks="viewChunks" @compare-evidence="viewEvidence"/>
      <EvidenceCompare v-else-if="page==='evidence'" :initial-document-id="evidenceFocus" @visual="viewVisual" @review="reviewDoc"/>
      <QualityPanel v-else-if="page==='quality'" :bases="bases" @task="id=>go('tasks','',id)" @review="reviewDoc" @document="viewChunks"/>
      <section v-else-if="isAdvanced" class="wb-legacy"><LegacyApp :key="page"/></section>
    </main>
    <div v-if="textOpen||editOpen" class="wb-modal-backdrop" @keydown="trapDialog" @click.self="!busy&&(textOpen=false,editOpen=false)" @keydown.esc="!busy&&(textOpen=false,editOpen=false)"><section class="wb-card wb-modal" role="dialog" aria-modal="true" :aria-label="textOpen?'纯文本入库':'编辑 Chunk'"><div class="wb-between"><h2>{{textOpen?'纯文本入库':'编辑 Chunk'}}</h2><button class="wb-icon-button" aria-label="关闭" :disabled="!!busy" @click="textOpen=false;editOpen=false"><Close/></button></div><form @submit.prevent="textOpen?importText():changeChunk({content:editBody})"><template v-if="textOpen"><label class="wb-field">知识库<select v-model="base"><option v-for="b in bases" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label class="wb-field">文档标题<input v-model="textTitle" required maxlength="180"/></label><label class="wb-field">正文<textarea v-model="textBody" required maxlength="200000" rows="12"/></label></template><label v-else class="wb-field">正文<textarea v-model="editBody" required maxlength="32000" rows="14"/></label><p v-if="error" role="alert" class="wb-error-text">{{error}}</p><div class="wb-actions"><button type="button" class="wb-button" :disabled="!!busy" @click="textOpen=false;editOpen=false">取消</button><button class="wb-button primary" :disabled="!!busy">{{busy?'正在保存…':'保存'}}</button></div></form></section></div>
  </div>
</template>
